    const L = g.lg > 0 ? g.lg : LEAGUE[sport].L;
    for (const [side, t] of [["advAway", g.away], ["advHome", g.home]]) { const r = powerRatios(PW[t.id], L); if (r) g[side] = { ...r, n: POWER_N[sport], source: sport === "NFL" || sport === "CFB" ? "FPI" : "BPI" }; }
