    out.push(makeBet({ bw, key: "sp-home", market: "SPR", side: "home", line: -L, odds: oH, w: p.gt, push: p.push, l: p.lt, fair: fH, label: `${H} ${fmtLine(-L)} (${fmtOdds(oH)})` }));
