    away: { name: r.md.away.name, abbr: r.md.away.abbr }, home: { name: r.md.home.name, abbr: r.md.home.abbr }, neutral: !!r.neutral,
    proj: { total, margin, rawTotal: total / (ln ? ln.s : 1), rawMargin: margin - (ln && !r.neutral ? ln.h : 0) },
