    if(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const c=ref.current,x=c.getContext("2d"),ch="アイウエオカキクケコサシスセソタチツテト0123456789ABCDEF";
    let w,h,cols,drops,id,last=0;
